param(
  [ValidateSet('', 'x86', 'x64')][string]$Platform = '',
  [switch]$SkipPluginTests,
  [string]$Source,
  [string]$Output,
  [switch]$UseInstalledCompiler
)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
if (!$Source) { $Source = Join-Path $repoRoot '.deps/dxvk-remix' }
if (!$Output) { $Output = Join-Path $repoRoot '.deps/pageblock-gc-test' }
$Source = [IO.Path]::GetFullPath($Source)
$Output = [IO.Path]::GetFullPath($Output)
if (!$Platform) {
  foreach ($arch in @('x86', 'x64')) {
    $childArgs = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $PSCommandPath, '-Platform', $arch, '-Source', $Source, '-Output', $Output)
    if ($SkipPluginTests) { $childArgs += '-SkipPluginTests' }
    if ($UseInstalledCompiler) { $childArgs += '-UseInstalledCompiler' }
    & powershell.exe @childArgs
    if ($LASTEXITCODE -ne 0) { throw "PageBlock $arch test process failed" }
  }
  exit 0
}
New-Item -ItemType Directory -Force $output | Out-Null
Push-Location $output
try {
  $arch = $Platform
  if ($UseInstalledCompiler) {
    . (Join-Path $PSScriptRoot 'setup_native_test_compiler.ps1')
    Set-NativeTestCompiler -Architecture $arch
  } else {
    . (Join-Path $source 'bridge/build_common.ps1')
    SetupVS -Platform $arch -VcVarsVer '14.29'
  }
  $compiler = (Get-Command cl.exe -ErrorAction Stop).Source
  [pscustomobject]@{architecture=$arch;compiler=$compiler;vc_tools_version=$env:VCToolsVersion;windows_sdk_version=$env:WindowsSDKVersion;formal_ci_toolset_equivalence=(!$UseInstalledCompiler -and $env:VCToolsVersion.StartsWith('14.29'))} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $output "compiler-$arch.json") -Encoding UTF8
  $pointerBytes = if ($arch -eq 'x86') { 4 } else { 8 }
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/DEXPECTED_POINTER_BYTES=$pointerBytes" "/I$source/bridge/src/server" "/I$source/bridge/src/client" "/I$source/bridge/src/util" "$repoRoot/tests/pageblock_residency.cpp" "/Fe:pageblock-$arch.exe" /link bcrypt.lib
  if ($LASTEXITCODE -ne 0) { throw "PageBlock GC $arch compilation failed" }
  & ".\pageblock-$arch.exe"
  if ($LASTEXITCODE -ne 0) { throw "PageBlock GC $arch tests failed: $LASTEXITCODE" }
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /utf-8 "/I$source/bridge/src/client" "/I$source/bridge/src/util" "$repoRoot/tests/bridge_settings.cpp" "/Fe:bridge-settings-$arch.exe"
  if ($LASTEXITCODE -ne 0) { throw "Common Bridge settings $arch compilation failed" }
  & ".\bridge-settings-$arch.exe"
  if ($LASTEXITCODE -ne 0) { throw "Common Bridge settings $arch tests failed: $LASTEXITCODE" }
  # Existing upstream Config/util headers retain these unrelated warnings. New settings/editor tests stay /W4 /WX.
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /utf-8 /DNOMINMAX /wd4100 /wd4505 /wd4189 /wd4996 /wd4459 /wd4267 "/I$source/bridge/src/util" "/I$source/public/include" "$repoRoot/tests/bridge_config.cpp" "$source/bridge/src/util/config/config.cpp" "$source/bridge/src/util/util_filesys.cpp" "/Fe:bridge-config-$arch.exe" /link psapi.lib shlwapi.lib
  if ($LASTEXITCODE -ne 0) { throw "Actual Config $arch compilation failed" }
  & ".\bridge-config-$arch.exe"
  if ($LASTEXITCODE -ne 0) { throw "Actual Client Config $arch tests failed: $LASTEXITCODE" }
  $hostDirectory = Join-Path $output '.l4d2bridge'
  New-Item -ItemType Directory -Force $hostDirectory | Out-Null
  $hostExecutable = Join-Path $hostDirectory "bridge-config-$arch.exe"
  Copy-Item ".\bridge-config-$arch.exe" $hostExecutable -Force
  & $hostExecutable --server
  if ($LASTEXITCODE -ne 0) { throw "Actual Host Config $arch tests failed: $LASTEXITCODE" }
  $unicodeDirectory = Join-Path $output ('config-' + [char]0x914d + [char]0x7f6e)
  New-Item -ItemType Directory -Force $unicodeDirectory | Out-Null
  $unicodeExecutable = Join-Path $unicodeDirectory "bridge-config-$arch.exe"
  Copy-Item ".\bridge-config-$arch.exe" $unicodeExecutable -Force
  & $unicodeExecutable
  if ($LASTEXITCODE -ne 0) { throw "Unicode Config path $arch tests failed: $LASTEXITCODE" }
  # Chinese is representable by CP936. A supplementary character also detects
  # lossy narrow-path conversion on Chinese Windows, without changing its ACP.
  $nonAcpDirectory = Join-Path $output ('config-' + [char]0x914d + [char]0x7f6e + '-' + [char]::ConvertFromUtf32(0x1f600))
  New-Item -ItemType Directory -Force $nonAcpDirectory | Out-Null
  $nonAcpExecutable = Join-Path $nonAcpDirectory "bridge-config-$arch.exe"
  Copy-Item ".\bridge-config-$arch.exe" $nonAcpExecutable -Force
  & $nonAcpExecutable
  if ($LASTEXITCODE -ne 0) { throw "Non-ACP Client Config path $arch tests failed: $LASTEXITCODE" }
  $nonAcpHostDirectory = Join-Path $nonAcpDirectory '.l4d2bridge'
  $nonAcpHostExecutable = Join-Path $nonAcpHostDirectory "bridge-config-$arch.exe"
  Copy-Item ".\bridge-config-$arch.exe" $nonAcpHostExecutable -Force
  & $nonAcpHostExecutable --server
  if ($LASTEXITCODE -ne 0) { throw "Non-ACP Host Config path $arch tests failed: $LASTEXITCODE" }
  if ($arch -eq 'x86' -and !$SkipPluginTests) {
    foreach ($mode in @('modern', 'old-general', 'legacy', 'missing')) {
      $compileArgs = @('/nologo', '/std:c++17', '/EHsc', '/W4', '/WX', '/utf-8', '/wd4100', "/I$source/bridge/src/util", "/I$source/bridge/src/client", "$repoRoot/tests/l4n_plugin.cpp", "/Fe:l4n-plugin-$mode.exe")
      if ($mode -eq 'modern' -or $mode -eq 'old-general') { $compileArgs += '/DL4D2_TEST_GENERAL' }
      if ($mode -eq 'old-general') { $compileArgs += '/DL4D2_TEST_OLD_GENERAL' }
      if ($mode -eq 'missing') { $compileArgs += '/DL4D2_TEST_NO_API' }
      $compileArgs += '/link'
      if ($mode -ne 'missing') { $compileArgs += '/EXPORT:L4D2BridgePageBlockControl=_L4D2BridgePageBlockControl@8' }
      if ($mode -eq 'modern' -or $mode -eq 'old-general') { $compileArgs += '/EXPORT:L4D2BridgeControl=_L4D2BridgeControl@8' }
      & cl.exe @compileArgs
      if ($LASTEXITCODE -ne 0) { throw "L4N $mode test compilation failed" }
      & ".\l4n-plugin-$mode.exe" (Join-Path $repoRoot '.deps/l4n-plugin/L4D2BridgePlugin.dll')
      if ($LASTEXITCODE -ne 0) { throw "L4N $mode callback tests failed: $LASTEXITCODE" }
    }
  }
} finally { Pop-Location }
